def zero_count(nums):
    """Write a function to find the ration of zeroes in an array of integers.

    Return the number of elements equal to ``0`` divided by the total
    number of elements, rounded to two decimal places. An empty array
    has a ratio of ``0.0``.
    """
    values = list(nums)
    if not values:
        return 0.0
    return round(values.count(0) / len(values), 2)
